INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-integrationcasestudywitemmd-65b0ef9a', NULL, 'integration_casestudy_wItem.md', 'This document outlines a comprehensive software integration strategy designed to unify three independently operating systems: Opcenter APS (production scheduling), UiPath (RPA), and SAS Viya (data analytics). Its primary purpose is to address operational inefficiencies, fragmented processes, and data silos by establishing a robust, AI-driven integration architecture. The strategy aims to create a cohesive ecosystem that enhances productivity, enables data-driven decision-making, and centralizes ...', 777, 'integration_casestudy_wItem.md', '{"tags": ["file_upload", "seeded_knowledge", "markdown"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/integration_casestudy_wItem.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-04-09 07:33:52+0000', '2026-04-09 07:33:52+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-archoncoreoverviewmd-33eb912b', NULL, 'archon_core_overview.md', 'Archon is an advanced Human-AI collaboration ecosystem designed to support business operations and technical development. It streamlines operations through key components like the Librarian, which manages automated knowledge archival and indexing. The Sentinel monitors system integrity and triggers automated repairs, while the Identity Matrix provides dynamic Role-Based Access Control (RBAC) governance. Its purpose is to facilitate efficient, secure, and well-governed AI-assisted collaboration w...', 72, 'archon_core_overview.md', '{"tags": ["file_upload", "seeded_knowledge", "markdown"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/archon_core_overview.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-04-09 07:34:17+0000', '2026-04-09 07:34:17+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-userinterfacemd-c7e6057c', NULL, 'user_interface.md', 'This document outlines the functional and screen requirements for a user settings system that allows individuals to register and configure multiple AI services (e.g., ChatGPT, Claude, Perplexity). Users can select desired AI services, input and verify their API credentials, and view free usage quotas for each. The system incorporates an email verification process for account creation and defines specific API endpoints for backend engineers to handle credential management, quota retrieval, and ov...', 187, 'user_interface.md', '{"tags": ["file_upload", "seeded_knowledge", "markdown"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/user_interface.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-04-09 07:35:01+0000', '2026-04-09 07:35:01+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-apdf-ba81ac34', NULL, 'a.pdf', 'This document, "Enterprise Integration and Digital Transformation Blueprint," outlines a strategic roadmap for unifying a company''s disparate software systems: Opcenter APS (production scheduling), UiPath (RPA and automation), and SAS Viya (data analytics). The core purpose is to transform these independent tools into a cohesive, intelligent platform for integrated resource, time, and work management. By leveraging APIs, event-driven architectures, and AI, alongside open-source tools like Git an...', 3776, 'a.pdf', '{"tags": ["file_upload", "seeded_knowledge", "pdf"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/pdfs/a.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-04-09 07:35:30+0000', '2026-04-09 07:35:30+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-cpdf-1d005c94', NULL, 'c.pdf', 'This document is a comprehensive market entry strategy report for a lithium battery manufacturer looking to expand into South Africa by 2025. It details significant growth opportunities in the South African electric vehicle (EV) and energy storage system (ESS) markets, driven by increasing demand and government incentives for local manufacturing.
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-dpdf-e8b953ad', NULL, 'd.pdf', 'This document outlines a strategic and technical blueprint to address the fragmentation of core business systems: Opcenter APS for production scheduling, UiPath for basic automation, and SAS Viya Studio for data analytics. The current independent operation of these systems leads to inefficiencies, manual processes, and high "search time costs."
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('style-lesson-81fb31bd', NULL, 'Style Lesson: Test Reject Blog', 'Style lesson learned from rejection of ''Test Reject Blog''', 96, 'Style Lesson: Test Reject Blog', '{"tags": ["brand_voice_constraint", "style_lesson", "bob_feedback"], "source_type": "url", "auto_generated": false, "knowledge_type": "brand_voice", "update_frequency": 7}'::jsonb, '2026-05-01 03:37:05+0000', '2026-05-01 03:37:05+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-integrationcasestudywitemmd-bddc4d2c', NULL, 'integration_casestudy_wItem.md', '這份文件並非軟體庫或框架，而是一份關於 **Opcenter APS、UiPath 與 SAS Viya 三大系統的企業級整合策略規劃書**。其目的在於打破現有各軟體獨立運作的數據孤島，透過建立統一的數據層、事件驅動架構及 API 串接，實現生產排程、自動化作業與數據分析的無縫協作。該策略強調利用 AI 技術加速開發，並導入標準化流程（如 Git 版本控制與 CI/CD），旨在提升整體營運效率、強化數據決策能力並推動企業自動化轉型。', 777, 'integration_casestudy_wItem.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/integration_casestudy_wItem.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 08:58:03+0000', '2026-05-23 08:58:03+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-archoncoreoverviewmd-4f6049b7', NULL, 'archon_core_overview.md', 'Archon is a comprehensive Human-AI collaboration ecosystem built to support business operations and technical development. It utilizes three core components—Librarian, Sentinel, and the Identity Matrix—to manage knowledge indexing, system integrity monitoring, and dynamic role-based governance. Ultimately, the framework is designed to provide a secure, automated, and self-repairing infrastructure for organizational workflows.', 72, 'archon_core_overview.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/archon_core_overview.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 08:58:30+0000', '2026-05-23 08:58:30+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-backendmd-b09f2f53', NULL, 'backend.md', 'ProjectFlow is a team-based task management platform designed to integrate seamlessly with external enterprise systems like Opcenter APS, UiPath, and Salesforce using an event-driven architecture. The backend, built with Node.js, Express, and PostgreSQL/Prisma, acts as a central data hub that synchronizes tasks and logs system events via a message queue (e.g., Apache Kafka). Its modular structure supports cross-platform collaboration through standardized API definitions and Docker-based developm...', 1216, 'backend.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/backend.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 08:58:39+0000', '2026-05-23 08:58:39+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-userinterfacemd-b6d409ae', NULL, 'user_interface.md', 'This document provides a comprehensive functional specification for an AI service configuration system. It outlines the end-to-end user workflow, including email verification, multi-service selection, credential validation, and quota tracking. The documentation serves as a technical guide for backend and frontend developers, defining the necessary API endpoints, data structures, and UI navigation flow to implement the complete user settings module.', 187, 'user_interface.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/user_interface.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 08:58:55+0000', '2026-05-23 08:58:55+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-apdf-414b6f96', NULL, 'a.pdf', '本文件為一份企業數位轉型藍圖，旨在整合 **Opcenter APS**（生產排程）、**UiPath**（流程自動化）與 **SAS Viya**（數據分析）三大獨立系統，以解決營運碎片化問題。該策略透過引入 API 與事件驅動架構（如 Apache Kafka），建立統一的資源、時間與工作管理平台，目標是提升生產力、降低營運成本並實現數據驅動的智慧決策。此外，文件中提出了具體的技術導入建議（如使用 Git 與開源工具作為整合黏著劑）及明確的績效考核機制，以確保企業在三年內達成策略性營收成長。', 3776, 'a.pdf', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/pdfs/a.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 08:59:07+0000', '2026-05-23 08:59:07+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-cpdf-fc8934a9', NULL, 'c.pdf', '這份文件並非軟體庫或開發框架，而是一份關於**南非鋰電池市場的綜合擴張策略簡報**。該報告旨在為面臨營收下滑的製造商提供進入南非市場的戰略指導，重點涵蓋市場需求分析（電動車與儲能系統）、監管與合規要求（如 SABS 認證、EPR 法規、外匯管制）、物流挑戰以及設廠建議。透過分階段的「電芯供應—本地組裝—技術落地」模式，協助企業利用政府激勵措施並克服當地市場的結構性風險。', 3751, 'c.pdf', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/pdfs/c.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 09:06:00+0000', '2026-05-23 09:06:00+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-bpdf-4fd3f6b3', NULL, 'b.pdf', '這份文件並非軟體庫或工具的說明書，而是一份關於**「企業整合與數位轉型藍圖」的策略規劃報告**。該計畫旨在將公司現有的三個核心系統——**Opcenter APS**（生產排程）、**UiPath**（流程自動化）與 **SAS Viya**（數據分析）進行深度串接，建立一個統一的資源、時間與工作管理平台。透過導入事件驅動架構、開源工具（如 Git、Kafka）及 AI 技術，該策略旨在消除數據孤島、自動化重複性流程，並實現數據驅動的決策循環，以提升整體營運效率並達成三年內的策略性成長目標。', 3776, 'b.pdf', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/pdfs/b.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 09:06:26+0000', '2026-05-23 09:06:26+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-dpdf-b3c0d210', NULL, 'd.pdf', '這份文件並非關於特定軟體庫或框架的說明，而是一份針對企業數位轉型的整合策略藍圖。其核心目的是將現有的 **Opcenter APS**（生產排程）、**UiPath**（流程自動化）與 **SAS Viya**（數據分析）進行系統性整合，打破資訊孤島並建立統一的資源與工作管理平台。透過導入事件驅動架構、API 標準化及 AI 技術，該策略旨在解決人工流程繁瑣與數據碎片化問題，進而提升企業的營運效率、決策能力及市場競爭力。', 2857, 'd.pdf', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/aus/156_resource/pdfs/d.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 09:07:22+0000', '2026-05-23 09:07:22+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-geminiintromp4-4c61668d', NULL, 'gemini_intro.mp4', '`gemini_intro.mp4` is a marketing video asset designed to showcase the capabilities of human-AI collaboration within the system. It serves as a visual demonstration tool to illustrate how users interact with and leverage Gemini''s features. The video is intended for promotional and educational purposes to highlight the integration and practical application of the AI.', 2, 'gemini_intro.mp4', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/gemini_intro.mp4", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-23 09:08:13+0000', '2026-05-23 09:08:13+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-contributingtwmd-73ab4c54', NULL, 'CONTRIBUTING_tw.md', '**Archon 廚房**（Project Cookbook）是一份專為團隊協作打造的標準作業流程 (SOP) 與開發規範指南，旨在確保專案在雲原生環境下的架構一致性與技術債控制。它透過嚴謹的「核心心法」、自動化測試門禁（如數位孿生偵察員、資料庫冪等遷移）以及明確的環境設定，定義了從開發、部署到 AI Agent 協作的標準作業模式。該文件的核心目的在於透過結構化的指令來源（Makefile）與品質檢核機制，實現開發流程的物理驗證與高品質交付。', 3606, 'CONTRIBUTING_tw.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/CONTRIBUTING_tw.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-23 09:08:17+0000', '2026-05-23 09:08:17+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-fanoutexecutivesummarywebm-39c2b7eb', NULL, 'fanout_executive_summary.webm', 'Content from file-fanoutexecutivesummarywebm-39c2b7eb', 7, 'fanout_executive_summary.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/fanout_executive_summary.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 00:17:52+0000', '2026-05-26 00:17:52+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-marketingdemowebm-9bd59a68', NULL, 'marketing_demo.webm', '**Archon** is a human-AI collaborative framework designed to automate complex workflows through a "multi-agent star-topology" system. It allows human administrators to assign tasks to a Supervisor Agent, which autonomously dispatches specialized AI agents—such as developers and analysts—to coordinate and execute sub-tasks. By facilitating real-time, cross-agent communication within a unified interface, Archon eliminates manual coordination gaps and delivers integrated, high-level outputs.', 42, 'marketing_demo.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/marketing_demo.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-24 09:23:38+0000', '2026-05-24 09:23:38+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-backendmd-505eb2a5', NULL, 'backend.md', 'ProjectFlow 是一個基於 Web 的團隊任務管理平台，採用事件驅動架構與 API 優先策略，旨在無縫整合外部系統（如 Opcenter APS、UiPath）。該系統使用 Node.js、Express、PostgreSQL 與 Prisma 構建，並引入 Kafka 作為訊息佇列以實現系統間的解耦。開發環境透過 Docker Compose 進行標準化管理，目前支援任務 CRUD、成員指派及專案進度追蹤等核心功能。', 1216, 'backend.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/backend.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-25 00:13:41+0000', '2026-05-25 00:13:41+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-bpdf-6b9da449', NULL, 'b.pdf', '這份文件並非關於單一軟體庫或框架，而是一份企業數位轉型策略藍圖，旨在整合 **Opcenter APS**（生產排程）、**UiPath**（流程自動化）與 **SAS Viya**（數據分析）三大獨立系統。該計畫透過引入 **Git** 版本控制、**Kafka** 事件驅動架構與 **PostgreSQL** 統一數據層，將碎片化的營運工具串聯為一個智慧化的資源與工作管理平台。其核心目的在於消除資訊孤島、降低「搜尋時間成本」，並透過 AI 賦能與嚴謹的 KPI 問責機制，實現企業營運的全面優化與策略性營收成長。', 3776, 'b.pdf', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///app/frontend_public/aus/156_resource/pdfs/b.pdf", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-25 00:16:02+0000', '2026-05-25 00:16:02+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-geminiintromp4-d5ee6412', NULL, 'gemini_intro.mp4', 'This file, `gemini_intro.mp4`, serves as a marketing and demonstration video asset. Its primary purpose is to showcase the capabilities and workflow of human-AI collaboration within the system. It functions as a visual resource to help users understand how the AI integrates into operational tasks.', 2, 'gemini_intro.mp4', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///app/frontend_public/assets/videos/auto_demos/gemini_intro.mp4", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-25 00:17:18+0000', '2026-05-25 00:17:18+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-marketingdemowebm-c76f862b', NULL, 'marketing_demo.webm', '**Archon** is a human-AI collaboration framework designed to automate complex workflows through a multi-agent "star-topology" architecture. By leveraging a centralized Supervisor Agent, it coordinates specialized agents—such as developers and analysts—within a unified, chat-based interface to complete tasks autonomously. This system eliminates communication gaps by allowing AI agents to collaborate and synthesize data in real-time, effectively closing the loop from task assignment to final repor...', 42, 'marketing_demo.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///app/frontend_public/assets/videos/auto_demos/marketing_demo.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-25 00:17:41+0000', '2026-05-25 00:17:41+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-contributingtwmd-e58a14d0', NULL, 'CONTRIBUTING_tw.md', '**Archon** 是一個專為開發具備 AI Agent 協作能力的雲端服務系統所設計的專案框架與作業流程指南。該專案整合了後端 API 服務、前端 UI 介面以及資料庫遷移管理，並定義了嚴謹的「開發食譜 (Project Cookbook)」來規範測試標準、自動化驗證機制與 Git 工作流程。其核心目標是透過標準化 SOP 與品質門禁（如自動化修復迴圈、Persona 稽核），確保在雲原生架構下開發具備高度穩定性與一致性的 AI 驅動應用程式。', 3672, 'CONTRIBUTING_tw.md', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///app/CONTRIBUTING_tw.md", "auto_generated": false, "knowledge_type": "technical", "update_frequency": 7}'::jsonb, '2026-05-25 00:17:48+0000', '2026-05-25 00:17:48+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-checkworkbenchvideowebm-603618b7', NULL, 'check_workbench_video.webm', '`check_workbench_video` is a tool designed for the automated verification of system workflows within a testing environment. It serves as visual documentation and empirical evidence for End-to-End (E2E) Model-Based Testing (MBT) processes. By capturing the execution of specific scenarios, it ensures that system functions operate as intended and provides a verifiable record for quality assurance.', 7, 'check_workbench_video.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/check_workbench_video.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 01:52:21+0000', '2026-05-26 01:52:21+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-bobmarketreportwebm-40aed68a', NULL, 'bob_market_report.webm', 'The `bob_market_report` system is an automated solution designed for end-to-end (E2E) Model-Based Testing (MBT). This specific documentation serves as a visual record and verification proof of the system''s automated validation processes in a real-world environment. It demonstrates how the tool executes and validates scenarios within the `bob_market_report` workflow, ensuring system reliability and functional accuracy.', 7, 'bob_market_report.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/bob_market_report.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 07:41:39+0000', '2026-05-26 07:41:39+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-alicehuntermodewebm-6b3f518c', NULL, 'alice_hunter_mode.webm', 'The `alice_hunter_mode` is a specialized system component designed for automated verification within a Model-Based Testing (MBT) framework. It serves as an end-to-end (E2E) testing tool that validates system workflows through automated, executable scenarios. Its primary purpose is to provide documented, visual evidence of successful system operations, ensuring the reliability and functional integrity of the target environment.', 7, 'alice_hunter_mode.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/alice_hunter_mode.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 07:59:36+0000', '2026-05-26 07:59:36+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-alicevisitlogwebm-d6cc420f', NULL, 'alice_visit_log.webm', 'The `alice_visit_log` is a system component or scenario used for automated validation testing. This specific asset, `file-alicevisitlogwebm-d6cc420f`, serves as a recorded video demonstration of the system''s E2E (End-to-End) Model-Based Testing (MBT) process. Its primary purpose is to provide visual documentation and proof that the automated verification workflows are functioning correctly within the system.', 7, 'alice_visit_log.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/alice_visit_log.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 08:09:40+0000', '2026-05-26 08:09:40+0000') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.archon_sources (source_id, source_url, source_display_name, summary, total_word_count, title, metadata, created_at, updated_at) VALUES ('file-bobpitchgenerationwebm-876bcc4a', NULL, 'bob_pitch_generation.webm', '`bob_pitch_generation` is a system designed to automate the generation of pitch-related tasks or content. This specific documentation highlights the use of an automated validation process to confirm system performance through end-to-end (E2E) Model-Based Testing (MBT). By providing visual evidence of these automated workflows, the tool ensures the reliability and functional integrity of the pitch generation process.', 7, 'bob_pitch_generation.webm', '{"tags": ["file_upload", "seeded_knowledge"], "source_type": "file", "original_url": "file:///Users/vincenta/GoogleKwok022/Archon/enduser-ui-fe/public/assets/videos/auto_demos/bob_pitch_generation.webm", "auto_generated": false, "knowledge_type": "marketing", "update_frequency": 7}'::jsonb, '2026-05-26 23:42:13+0000', '2026-05-26 23:42:13+0000') ON CONFLICT (source_id) DO NOTHING;
